const workflowName = $json.workflow?.name || 'Inconnu';
const nodeName = $json.execution?.lastNodeExecuted || 'Inconnu';
const errorMessage = $json.execution?.error?.message || 'Erreur sans message';
const executionUrl = $json.execution?.url || '';
const executionId = $json.execution?.id || '';

return {
  json: {
    type_incident: 'defaillance_technique',
    description: `Echec du workflow "${workflowName}" au noeud "${nodeName}": ${errorMessage} (execution ${executionId})`,
    gravite: 'moyenne',
    detecte_par: 'n8n_error_workflow_automatique',
    workflow_name: workflowName,
    node_name: nodeName,
    error_message: errorMessage,
    execution_url: executionUrl,
    execution_id: executionId
  }
};
